async () => {
  const paths = [
    '/!api/2.0/repositories/healshealthcare/heals-app-rn/pullrequests/564',
    '/api/2.0/repositories/healshealthcare/heals-app-rn/pullrequests/564',
  ];
  const results = [];
  for (const path of paths) {
    try {
      const resp = await fetch(path, {credentials: 'include', headers: {Accept: 'application/json'}});
      const text = await resp.text();
      results.push({path, status: resp.status, ctype: resp.headers.get('content-type'), head: text.slice(0, 300)});
    } catch (e) {
      results.push({path, error: String(e)});
    }
  }
  const text = document.body ? document.body.innerText.slice(0, 2500) : '';
  return {title: document.title, url: location.href, text, results};
}

