const ts = require('typescript');
const path = require('path');
const {execSync} = require('child_process');
const root = process.cwd();
const configPath = ts.findConfigFile(root, ts.sys.fileExists, 'tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, root);
const program = ts.createProgram({rootNames: parsed.fileNames, options: parsed.options});

const changed = execSync('git diff --name-only ab9686512b0a3ad62d7f18fb97cf35d643c31e17...HEAD -- "*.ts" "*.tsx"', {encoding:'utf8'}).trim().split('\n');

function rangesFor(rel) {
  const diff = execSync(`git diff -U0 ab9686512b0a3ad62d7f18fb97cf35d643c31e17...HEAD -- ${rel}`, {encoding:'utf8'});
  const ranges = [];
  const re = /@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/g;
  let m;
  while ((m = re.exec(diff))) {
    const start = Number(m[1]);
    const count = m[2] === undefined ? 1 : Number(m[2]);
    if (count > 0) ranges.push([start, start + count - 1]);
  }
  return ranges;
}
function inRange(ranges, line) {
  return ranges.some(([a,b]) => line >= a && line <= b);
}

for (const rel of changed) {
  const abs = path.join(root, rel);
  const sf = program.getSourceFile(abs);
  if (!sf) { console.log('NO_SOURCE', rel); continue; }
  const ranges = rangesFor(rel);
  const diags = [
    ...program.getSyntacticDiagnostics(sf),
    ...program.getSemanticDiagnostics(sf),
    ...program.getSuggestionDiagnostics(sf),
  ];
  const hit = [];
  for (const d of diags) {
    const {line} = sf.getLineAndCharacterOfPosition(d.start ?? 0);
    const ln = line + 1;
    if (!inRange(ranges, ln)) continue;
    const msg = ts.flattenDiagnosticMessageText(d.messageText, ' ').slice(0, 220);
    hit.push(`${ts.DiagnosticCategory[d.category]} TS${d.code} ${rel}:${ln} ${msg}`);
  }
  if (hit.length) {
    console.log('---', rel, 'new-line diagnostics', hit.length);
    hit.forEach(x => console.log(x));
  } else {
    console.log('CLEAN_NEW_LINES', rel);
  }
}
